663	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
664	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
665		if accountID == "" {
666			return Usage{}, invalidf("account id is empty")
667		}
668		s.mu.Lock()
669		defer s.mu.Unlock()
670		acc, ok := s.accounts[accountID]
671		if !ok {
672			return Usage{}, ErrAccountNotFound
673		}
674		// 与其他入口保持一致：顺带让已到期的换套餐/取消生效。
675		s.settleLocked(acc, s.nowUTC())
676		return Usage{Period: period, Total: acc.usage[period]}, nil
